                aria-label="Fermer"
              >
                <X className="w-5 h-5 text-[var(--color-gray-600)]" />
              </button>

              <AnimatePresence mode="wait">
                {view === "login" ? (
                  <motion.div
                    key="login"
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    exit={{ opacity: 0, x: 20 }}
                    transition={{ duration: 0.2 }}
                  >
                    <LoginForm onSwitchToRegister={() => setView("register")} />
