            type="button"
            onClick={onSwitchToRegister}
            className="text-[var(--color-primary)] font-medium hover:underline"
          >
            S&apos;inscrire
          </button>
        </p>
      </div>
    </>
  );
}

function RegisterForm({ onSwitchToLogin }: { onSwitchToLogin: () => void }) {
