            </motion.div>
          ))}
        </motion.div>
      </div>

      {/* Navigation buttons */}
      <AnimatePresence>
        {canGoPrevious && (
          <motion.button
            initial={{ opacity: 0, x: 10 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: 10 }}
            onClick={goToPrevious}
            className="absolute left-0 top-1/2 -translate-y-1/2 -translate-x-1/2 z-10 w-12 h-12 bg-white border-2 border-[var(--color-black)] rounded-full shadow-[3px_3px_0px_var(--color-black)] flex items-center justify-center hover:shadow-[5px_5px_0px_var(--color-black)] hover:-translate-x-[calc(50%+2px)] hover:-translate-y-[calc(50%+2px)] transition-all opacity-0 group-hover:opacity-100"
            aria-label="Albums précédents"
          >
            <ChevronLeft className="w-6 h-6 text-[var(--color-black)]" />
          </motion.button>
        )}
      </AnimatePresence>

      <AnimatePresence>
        {canGoNext && (
          <motion.button
            initial={{ opacity: 0, x: -10 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -10 }}
            onClick={goToNext}
            className="absolute right-0 top-1/2 -translate-y-1/2 translate-x-1/2 z-10 w-12 h-12 bg-white border-2 border-[var(--color-black)] rounded-full shadow-[3px_3px_0px_var(--color-black)] flex items-center justify-center hover:shadow-[5px_5px_0px_var(--color-black)] hover:translate-x-[calc(50%+2px)] hover:-translate-y-[calc(50%+2px)] transition-all opacity-0 group-hover:opacity-100"
            aria-label="Albums suivants"
          >
            <ChevronRight className="w-6 h-6 text-[var(--color-black)]" />
          </motion.button>
        )}
      </AnimatePresence>

      {/* Progress indicator */}
      {totalPages > 1 && (
        <div className="flex items-center justify-center gap-2 mt-6">
          {/* Dots indicator */}
          <div className="flex items-center gap-2">
            {Array.from({ length: totalPages }).map((_, pageIndex) => (
              <button
                key={pageIndex}
                onClick={() => goToPage(pageIndex)}
                className={`transition-all duration-300 ${
                  pageIndex === currentPage
                    ? "w-8 h-3 bg-[var(--color-primary)] rounded-full"
                    : "w-3 h-3 bg-[var(--color-gray-300)] rounded-full hover:bg-[var(--color-gray-400)]"
                }`}
                aria-label={`Aller à la page ${pageIndex + 1}`}
                aria-current={pageIndex === currentPage ? "true" : undefined}
              />
            ))}
          </div>

          {/* Page counter */}
          <span className="ml-4 text-sm text-[var(--color-gray-500)] font-medium">
            {currentPage + 1} / {totalPages}
          </span>
        </div>
      )}
    </div>
  );
}

