     2→
     3→import { useState, useRef, useEffect, useCallback } from "react";
     4→import { motion, AnimatePresence } from "framer-motion";
     5→import { ChevronLeft, ChevronRight } from "lucide-react";
     6→import { AlbumCard } from "./AlbumCard";
     7→import type { Album } from "@/types";
     8→
     9→interface AlbumCarouselProps {
    10→  albums: Album[];
    11→  itemsPerView?: {
    12→    mobile: number;
    13→    tablet: number;
    14→    desktop: number;
    15→  };
    16→  autoPlay?: boolean;
    17→  autoPlayInterval?: number;
    18→}
    19→
    20→export function AlbumCarousel({
    21→  albums,
    22→  itemsPerView = { mobile: 2, tablet: 3, desktop: 5 },
    23→  autoPlay = false,
    24→  autoPlayInterval = 5000,
    25→}: AlbumCarouselProps) {
    26→  const [currentIndex, setCurrentIndex] = useState(0);
    27→  const [visibleItems, setVisibleItems] = useState(itemsPerView.desktop);
    28→  const [isDragging, setIsDragging] = useState(false);
    29→  const containerRef = useRef<HTMLDivElement>(null);
    30→  const dragStartX = useRef(0);
    31→  const dragOffset = useRef(0);
    32→
    33→  // Calculate visible items based on screen size
    34→  useEffect(() => {
    35→    const updateVisibleItems = () => {
    36→      if (window.innerWidth < 640) {
    37→        setVisibleItems(itemsPerView.mobile);
    38→      } else if (window.innerWidth < 1024) {
    39→        setVisibleItems(itemsPerView.tablet);
    40→      } else {
    41→        setVisibleItems(itemsPerView.desktop);
    42→      }
    43→    };
    44→
    45→    updateVisibleItems();
    46→    window.addEventListener("resize", updateVisibleItems);
    47→    return () => window.removeEventListener("resize", updateVisibleItems);
    48→  }, [itemsPerView]);
    49→
    50→  const totalPages = Math.ceil(albums.length / visibleItems);
    51→  const maxIndex = Math.max(0, albums.length - visibleItems);
    52→
    53→  // Auto-play functionality
    54→  useEffect(() => {
    55→    if (!autoPlay || totalPages <= 1) return;
    56→
    57→    const interval = setInterval(() => {
    58→      setCurrentIndex((prev) => {
    59→        const nextIndex = prev + visibleItems;
    60→        return nextIndex > maxIndex ? 0 : nextIndex;
    61→      });
    62→    }, autoPlayInterval);
    63→
    64→    return () => clearInterval(interval);
    65→  }, [autoPlay, autoPlayInterval, visibleItems, maxIndex, totalPages]);
    66→
    67→  const goToPage = useCallback(
    68→    (pageIndex: number) => {
    69→      const newIndex = pageIndex * visibleItems;
    70→      setCurrentIndex(Math.min(newIndex, maxIndex));
    71→    },
    72→    [visibleItems, maxIndex]
    73→  );
    74→
    75→  const goToPrevious = useCallback(() => {
    76→    setCurrentIndex((prev) => Math.max(0, prev - visibleItems));
    77→  }, [visibleItems]);
    78→
    79→  const goToNext = useCallback(() => {
    80→    setCurrentIndex((prev) => Math.min(maxIndex, prev + visibleItems));
    81→  }, [maxIndex, visibleItems]);
    82→
    83→  // Touch/drag handlers
    84→  const handleDragStart = (e: React.MouseEvent | React.TouchEvent) => {
    85→    setIsDragging(true);
    86→    dragStartX.current = "touches" in e ? e.touches[0].clientX : e.clientX;
    87→    dragOffset.current = 0;
    88→  };
    89→
    90→  const handleDragMove = (e: React.MouseEvent | React.TouchEvent) => {
    91→    if (!isDragging) return;
    92→    const currentX = "touches" in e ? e.touches[0].clientX : e.clientX;
    93→    dragOffset.current = currentX - dragStartX.current;
    94→  };
    95→
    96→  const handleDragEnd = () => {
    97→    if (!isDragging) return;
    98→    setIsDragging(false);
    99→
   100→    const threshold = 50;
   101→    if (dragOffset.current > threshold) {
   102→      goToPrevious();
   103→    } else if (dragOffset.current < -threshold) {
   104→      goToNext();
   105→    }
   106→    dragOffset.current = 0;
   107→  };
   108→
   109→  // Keyboard navigation
   110→  useEffect(() => {
   111→    const handleKeyDown = (e: KeyboardEvent) => {
   112→      if (!containerRef.current?.contains(document.activeElement)) return;
   113→      if (e.key === "ArrowLeft") goToPrevious();
   114→      if (e.key === "ArrowRight") goToNext();
   115→    };
   116→
   117→    window.addEventListener("keydown", handleKeyDown);
   118→    return () => window.removeEventListener("keydown", handleKeyDown);
   119→  }, [goToPrevious, goToNext]);
   120→
   121→  const currentPage = Math.floor(currentIndex / visibleItems);
   122→  const canGoPrevious = currentIndex > 0;
   123→  const canGoNext = currentIndex < maxIndex;
   124→
   125→  if (albums.length === 0) return null;
   126→
   127→  return (
   128→    <div className="relative group" ref={containerRef} tabIndex={0}>
   129→      {/* Carousel container */}
   130→      <div
   131→        className="overflow-hidden"
   132→        onMouseDown={handleDragStart}
   133→        onMouseMove={handleDragMove}
   134→        onMouseUp={handleDragEnd}
   135→        onMouseLeave={handleDragEnd}
   136→        onTouchStart={handleDragStart}
   137→        onTouchMove={handleDragMove}
   138→        onTouchEnd={handleDragEnd}
   139→      >
   140→        <motion.div
   141→          className="flex gap-4 md:gap-6"
   142→          animate={{
   143→            x: `calc(-${currentIndex * (100 / visibleItems)}% - ${currentIndex * (visibleItems > 2 ? 24 : 16) / visibleItems}px)`,
   144→          }}
   145→          transition={{
   146→            type: "spring",
   147→            stiffness: 300,
   148→            damping: 30,
   149→          }}
   150→          style={{ cursor: isDragging ? "grabbing" : "grab" }}
   151→        >
   152→          {albums.map((album, index) => (
   153→            <motion.div
   154→              key={album.id}
