            <motion.div
              key={index}
              className="flex-shrink-0"
              style={{
                width:
                  itemWidth > 0
                    ? itemWidth
                    : `calc(${100 / visibleItems}% - ${((visibleItems - 1) * currentGap) / visibleItems}px)`,
