              >
                <AlbumCard album={album} priority={index < visibleItems} />
              </div>
            </motion.div>
          ))}
        </motion.div>
      </div>

      {/* Navigation buttons - always visible on hover */}
      {canGoPrevious && (
        <button
          onClick={goToPrevious}
          className="absolute left-2 top-1/2 -translate-y-1/2 z-10 w-11 h-11 bg-white border-2 border-[var(--color-black)] rounded-full shadow-[3px_3px_0px_var(--color-black)] flex items-center justify-center hover:shadow-[4px_4px_0px_var(--color-black)] hover:-translate-y-[calc(50%+1px)] hover:translate-x-[-1px] transition-all opacity-0 group-hover:opacity-100 focus:opacity-100"
